    modelOwn: tr("own values", "eigene Werte", "собственные значения", "valores próprios", "eigen waarden", "valeurs propres", "valori propri", "valores propios", "własne wartości", "власні значення", "自定义数值"),
    archiveEmpty: tr("There are no old templates to remove.", "Es gibt keine alten Vorlagen, die entfernt werden könnten.", "Нет старых шаблонов для удаления.", "Não há modelos antigos para remover.", "Er zijn geen oude sjablonen om te verwijderen.", "Il n'y a aucun ancien modèle à supprimer.", "Non ci sono vecchi modelli da rimuovere.", "No hay plantillas antiguas que eliminar.", "Brak starych szablonów do usunięcia.", "Немає старих шаблонів для видалення.", "没有可删除的旧模板。"),
    needsReview: (hint) => tr(`Check the device and save it: ${hint}`, `Gerät prüfen und speichern: ${hint}`, `Проверьте и сохраните устройство: ${hint}`, `Verifique e guarde o dispositivo: ${hint}`, `Controleer het apparaat en sla het op: ${hint}`, `Vérifiez l'appareil et enregistrez-le : ${hint}`, `Controlla il dispositivo e salvalo: ${hint}`, `Compruebe el dispositivo y guárdelo: ${hint}`, `Sprawdź urządzenie i zapisz je: ${hint}`, `Перевірте пристрій і збережіть його: ${hint}`, `请检查设备并保存：${hint}`),
    notFound: tr("Device not found.", "Gerät nicht gefunden.", "Устройство не найдено.", "Dispositivo não encontrado.", "Apparaat niet gevonden.", "Appareil introuvable.", "Dispositivo non trovato.", "Dispositivo no encontrado.", "Nie znaleziono urządzenia.", "Пристрій не знайдено.", "未找到设备。"),
